"""Pure conversion of pinned App Server items, after native source validation.

No process, retry, storage or request settlement lives here. Complete items
retain the provider's fields in the existing transcript's tool_input object.
"""

from __future__ import annotations

import base64
import hashlib
import json
from typing import Any

from .codex import _mcp_result_text
from .events import HarnessEvent
from .profile import ParseOutput

# Pinned image extension accepts at most 32 MiB of decoded generated bytes.
# Only this protocol's reader grows; queues and ordinary text keep their limits.
IMAGE_BYTES = 32 * 1024 * 1024
NATIVE_LINE_BYTES = ((IMAGE_BYTES + 2) // 3) * 4 + 4 * 1024 * 1024
TEXT_FRAME_BYTES = 4 * 1024 * 1024


def observation_frame(obj: dict[str, Any]) -> dict[str, Any]:
    """Discard inline media at the wire boundary, retaining a content identity.

    Native savedPath is the only file authority. Inline bytes are verified but
    never copied to a new media root, DB, WS or raw event queue.
    """
    params = obj.get("params") or {}
    item = params.get("item") or {}
    if obj.get("method") in {"item/started", "item/completed"} and item.get("type") == "imageGeneration":
        projected = {key: value for key, value in item.items() if key != "result"}
        if "fileId" in item:
            if not isinstance(item["fileId"], str) or not item["fileId"]:
                raise ValueError("Native image fileId is invalid")
        else:
            encoded = item.get("result")
            if not isinstance(encoded, str):
                raise ValueError("Native image has no fileId or inline result")
            if len(encoded) > ((IMAGE_BYTES + 2) // 3) * 4:
                raise ValueError(f"Native generated image exceeds {IMAGE_BYTES} byte decoded budget")
            decoded = base64.b64decode(encoded.strip(), validate=True)
            if len(decoded) > IMAGE_BYTES:
                raise ValueError(f"Native generated image exceeds {IMAGE_BYTES} byte decoded budget")
            projected["inlineImage"] = {"bytes": len(decoded), "sha256": hashlib.sha256(decoded).hexdigest()}
        obj = {**obj, "params": {**params, "item": projected}}
    if len(json.dumps(obj, ensure_ascii=False).encode()) > TEXT_FRAME_BYTES:
        raise ValueError(f"Native non-media frame exceeds {TEXT_FRAME_BYTES} byte budget")
    return obj


def diagnostic_frame(obj: dict[str, Any]) -> dict[str, Any]:
    params = obj.get("params") or {}
    item = params.get("item") or {}
    if item.get("type") != "imageGeneration" or "result" not in item:
        return obj
    return {**obj, "params": {**params, "item": {**item, "result": "<inline media omitted>"}}}


def item_events(method: str, params: dict[str, Any]) -> ParseOutput:
    item = params["item"]
    kind, identifier = item.get("type"), item["id"]
    started = method == "item/started"
    if kind == "userMessage":
        return ParseOutput(activity=False)  # Original submission owns the input.
    if kind == "agentMessage":
        if started:
            return ParseOutput(activity=False)
        if not isinstance(item.get("text"), str):
            raise ValueError("Complete native message has no text")
        return ParseOutput(events=[HarnessEvent(type="text", content=item["text"],
            tool_input={"native_item": {key: value for key, value in item.items() if key != "text"}})])
    if kind == "reasoning":
        if started:
            return ParseOutput(activity=False)
        parts = [item.get("summary", []), item.get("content", [])]
        if any(not isinstance(part, list) or any(not isinstance(text, str) for text in part) for part in parts):
            raise ValueError("Malformed native reasoning")
        return ParseOutput(events=[HarnessEvent(type="thinking", content="\n".join(parts[0] + parts[1]),
            tool_input={"native_item": item})])

    name: str
    tool_input: dict[str, Any]
    content: str
    statuses = {
        "commandExecution": {"inProgress", "completed", "failed", "declined"},
        "fileChange": {"inProgress", "completed", "failed", "declined"},
        "mcpToolCall": {"inProgress", "completed", "failed"},
        "dynamicToolCall": {"inProgress", "completed", "failed"},
        "collabAgentToolCall": {"inProgress", "completed", "failed", "interrupted"},
    }
    if kind in statuses and item.get("status") not in statuses[kind]:
        raise ValueError(f"Invalid native {kind} status: {item.get('status')}")
    failed = item.get("status") in {"failed", "declined", "interrupted"}
    if kind == "commandExecution":
        name = "Bash"
        tool_input = {"command": item.get("command"), "native_item": item}
        content = item.get("aggregatedOutput") or ""
        failed |= item.get("exitCode") not in (0, None)
    elif kind == "mcpToolCall":
        name = f"mcp__{item.get('server', '')}__{item.get('tool', '')}"
        arguments = item.get("arguments")
        tool_input = {**(arguments if isinstance(arguments, dict) else {"arguments": arguments}), "native_item": item}
        error = item.get("error")
        content = _mcp_result_text(item.get("result"))
        if error is not None:
            content = "\n".join(part for part in (content, json.dumps(error, ensure_ascii=False)) if part)
        failed |= error is not None
    elif kind == "imageGeneration":
        name = kind
        status = item.get("status")
        if status not in {"in_progress", "completed", "failed"}:
            raise ValueError(f"Invalid native image generation status: {status}")
        path = item.get("savedPath")
        if path is not None and (not isinstance(path, str) or not path.startswith("/")):
            raise ValueError("Native saved image path is not absolute")
        failed = status == "failed" or item.get("failure") is not None
        content = ("Native image generation failed: " + json.dumps(item.get("failure"), ensure_ascii=False) if failed else
                   f"Generated image saved at: {path}" if path else
                   "Native image generation completed; local file unavailable." if status == "completed" else
                   "Native image generation in progress")
        tool_input = {"native_item": item}
    elif kind in {"imageView", "hookPrompt", "dynamicToolCall"}:
        name = item.get("tool") if kind == "dynamicToolCall" else kind
        name = name or kind
        if kind == "imageView" and not isinstance(item.get("path"), str):
            raise ValueError("Native image view has no path")
        if kind == "hookPrompt" and (not isinstance(item.get("fragments"), list) or any(
                not isinstance(fragment, dict) or not isinstance(fragment.get("text"), str)
                or not isinstance(fragment.get("hookRunId"), str) for fragment in item["fragments"])):
            raise ValueError("Malformed native hook prompt")
        tool_input = {"native_item": item}
        content = json.dumps(item, ensure_ascii=False)
        failed |= kind == "dynamicToolCall" and item.get("success") is False
    elif kind in {"collabAgentToolCall", "subAgentActivity", "webSearch", "fileChange", "contextCompaction"}:
        name = item.get("tool") or kind
        tool_input = params
        content = json.dumps(params, ensure_ascii=False)
    else:
        raise ValueError(f"Unsupported complete native item: {kind}")
    if started:
        return ParseOutput(events=[HarnessEvent(type="tool_use", tool_use_id=identifier,
            tool_name=name, tool_input=tool_input)])
    return ParseOutput(events=[HarnessEvent(type="tool_result", tool_use_id=identifier,
        tool_name=kind if kind == "fileChange" else name, tool_input={"native_item": item},
        content=content, is_error=failed)])
